using System;
using System.Diagnostics;
using System.Threading;

// PROGRAM: Memeriksa Kapasitas Hardware Thread & Utilisasi Core
Console.WriteLine($"=== INFORMASI CPU SERVER ===");
Console.WriteLine($"Logical Hardware Threads: {Environment.ProcessorCount}");
Console.WriteLine($"64-Bit Process: {Environment.Is64BitProcess}");
Console.WriteLine($"Current Managed Thread ID: {Environment.CurrentManagedThreadId}");

// Eksperimen pemanfaatan ALU: Kalkulasi intensif CPU
var sw = Stopwatch.StartNew();
long counter = 0;
for (int i = 0; i < 50_000_000; i++)
{
    counter += (i ^ 3) * 7; // Menggunakan operasi ALU integer perkalian dan XOR
}
sw.Stop();

Console.WriteLine($"Operasi ALU selesai dalam: {sw.ElapsedMilliseconds} ms (Checksum: {counter})");
