using System;

public class CpuSimulator
{
    public static int ExecuteInstructions(string[] instructions)
    {
        int r1 = 0;
        int r2 = 0;

        foreach (var inst in instructions)
        {
            if (string.IsNullOrWhiteSpace(inst)) continue;
            var parts = inst.Trim().Split(' ', StringSplitOptions.RemoveEmptyEntries);
            string op = parts[0].ToUpperInvariant();

            if (op == "ADD" && parts.Length > 1 && int.TryParse(parts[1], out int valAdd))
            {
                r1 += valAdd;
            }
            else if (op == "SUB" && parts.Length > 1 && int.TryParse(parts[1], out int valSub))
            {
                r1 -= valSub;
            }
            else if (op == "SWAP")
            {
                int temp = r1;
                r1 = r2;
                r2 = temp;
            }
        }

        return r1;
    }

    public static void Main()
    {
        string[] program = { "ADD 10", "SWAP", "ADD 5", "SUB 2" };
        Console.WriteLine($"Hasil R1: {ExecuteInstructions(program)}");
    }
}
